"""Generate the 200 language-coverage tests (ST/SFC/IL) for stc.

Run: python3 tools/gen_lang_tests.py
Then: PYTHONPATH=src python3 -m unittest discover -s tests -p "test_lang_*.py"
"""
from pathlib import Path

HEADER = '''# Copyright (C) 2021-2026 Manuele Conti
# SPDX-License-Identifier: GPL-2.0-or-later
"""{{doc}} (generated by tools/gen_lang_tests.py - do not edit by hand)."""

import unittest

from stc.compiler import compile_source


class {{cls}}(unittest.TestCase):
'''

METHOD_BOTH = '''
    def test_{mid}_{name}(self):
        source = """\\
{src}"""
        c_result = compile_source(source, "c", standard="{std}")
        self.assertTrue(c_result.success, c_result.diagnostics or c_result.syntax_error)
{r_c_checks}        rust_result = compile_source(source, "rust", standard="{std}")
        self.assertTrue(rust_result.success, rust_result.diagnostics or rust_result.syntax_error)
{r_r_checks}'''

METHOD_C = '''
    def test_{mid}_{name}(self):
        source = """\\
{src}"""
        result = compile_source(source, "c", standard="{std}")
        self.assertTrue(result.success, result.diagnostics or result.syntax_error)
{r_checks}'''

METHOD_NEG = '''
    def test_{mid}_{name}(self):
        source = """\\
{src}"""
        result = compile_source(source, "c", standard="{std}")
        self.assertFalse(result.success)
        codes = {{item.code for item in result.diagnostics}}
{r_checks}'''

METHOD_WARN = '''
    def test_{mid}_{name}(self):
        source = """\\
{src}"""
        result = compile_source(source, "c", standard="{std}")
        self.assertTrue(result.success, result.diagnostics or result.syntax_error)
        codes = {{item.code for item in result.diagnostics}}
{r_checks}'''


def check_in(marker):
    return f'        self.assertIn({marker!r}, output_placeholder)\n'


def emit(cases, path, doc, cls):
    out = [HEADER.replace("{{doc}}", doc).replace("{{cls}}", cls)]
    for case in cases:
        kind = case.get("kind", "both")
        if kind == "both":
            c_checks = "".join(f"        self.assertIn({m!r}, c_result.output)\n" for m in case.get("c_marks", []))
            r_checks = "".join(f"        self.assertIn({m!r}, rust_result.output)\n" for m in case.get("r_marks", []))
            out.append(METHOD_BOTH.format(mid=case["mid"], name=case["id"], src=case["src"], std=case.get("std", "ed3"), r_c_checks=c_checks, r_r_checks=r_checks))
        elif kind == "c":
            checks = "".join(f"        self.assertIn({m!r}, result.output)\n" for m in case.get("marks", []))
            out.append(METHOD_C.format(mid=case["mid"], name=case["id"], src=case["src"], std=case.get("std", "ed3"), r_checks=checks))
        elif kind == "neg":
            checks = "".join(f"        self.assertIn({m!r}, codes)\n" for m in case["codes"])
            out.append(METHOD_NEG.format(mid=case["mid"], name=case["id"], src=case["src"], std=case.get("std", "ed3"), r_checks=checks))
        elif kind == "warn":
            checks = "".join(f"        self.assertIn({m!r}, codes)\n" for m in case["codes"])
            out.append(METHOD_WARN.format(mid=case["mid"], name=case["id"], src=case["src"], std=case.get("std", "ed3"), r_checks=checks))
    out.append('\n\nif __name__ == "__main__":\n    unittest.main()\n')
    Path(path).write_text("".join(out), encoding="utf-8")
    print(f"{path}: {len(cases)} tests")


def FUN(name, rettype, decls, body):
    return f"FUNCTION {name} : {rettype}\n{decls}\n{body}\nEND_FUNCTION\n"


def PROG(name, decls, body):
    return f"PROGRAM {name}\n{decls}\n{body}\nEND_PROGRAM\n"


